 'use strict';
const SPACING={1:[2],2:[1,4],3:[0,2,4],4:[0,1,3,5],5:[0,1,2,4,5],6:[0,1,2,3,4,5],7:[0,1,2,3,4,5,6]};
const ROUTINES=['Push','Pull','Lower'];
function isRotation(p=profile()){return p.mode==='rotation';}
function nextWorkoutIndex(p=profile()){return (p.rotationIndex||0)%p.schedule.length;}
function defaultWorkoutIndex(){return isRotation()?nextWorkoutIndex():(new Date().getDay()+6)%7;}
function weeklyTarget(p=profile()){return isRotation(p)?(p.weeklyTarget||5):p.schedule.filter(d=>d.type!=='Rest').length;}
function draftForProfile(){const p=profile(),selected=!isRotation()?p.schedule.map((d,i)=>d.type==='Rest'?-1:i).filter(i=>i>=0):SPACING[weeklyTarget(p)];return {mode:p.mode||'rotation',target:p.weeklyTarget||5,sequence:['Push','Pull','Lower'],days:selected?.length?selected.slice():SPACING[5].slice(),equipment:p.equipment.slice(),bans:p.bans.slice(),assignments:!isRotation(p)?Object.fromEntries(p.schedule.map((d,i)=>[i,d.type]).filter(([,t])=>ROUTINES.includes(t))):{},step:1};}
function openSetup(){if(hasActive()){toast('Finish or reset your active workout before changing setup.');return;}setupDraft=draftForProfile();if(isRotation()&&profile().schedule.every(d=>ROUTINES.includes(d.type)))setupDraft.sequence=profile().schedule.map(d=>d.type);tab='Setup';focusMode=false;render();}
function plannedProfile(){const d=setupDraft,p={...profile(),mode:d.mode,weeklyTarget:d.target,equipment:d.equipment,bans:d.bans},days=d.days.slice().sort((a,b)=>a-b);p.schedule=d.mode==='rotation'?d.sequence.map(type=>({type,custom:null})):DAYS.map((_,i)=>({type:days.includes(i)?(d.assignments[i]||d.sequence[days.indexOf(i)%d.sequence.length]):'Rest',custom:null}));return p;}
function setupView(){setupDraft??=draftForProfile();const d=setupDraft,n=d.mode==='rotation'?d.target:d.days.length;return `<div class="setup-heading"><div class="eyebrow">SETUP</div><h1>Workout setup</h1><p class="muted">Choose your equipment, schedule type and weekly target.</p></div><div class="setup-layout"><aside class="setup-steps">${['Your equipment','Your schedule','Your new plan'].map((t,i)=>`<button data-setup="step" data-value="${i+1}" class="${d.step===i+1?'selected':''}"><span>0${i+1}</span>${t}</button>`).join('')}<div class="setup-note"><strong>20 min × ${n} sessions</strong><p>${n*20} minutes per week.<br>${d.mode==='rotation'?'Workouts repeat in order.':'Your fixed weekly schedule.'}</p></div></aside><section class="section setup-content">${d.step===1?equipmentStep():d.step===2?daysStep():previewStep()}</section></div>`;}
function equipmentStep(){const d=setupDraft;return `<div class="eyebrow">01 / EQUIPMENT</div><h2>Available equipment</h2><p>Only selected equipment will appear in your workouts and alternatives.</p><div class="equipment-grid">${EQUIPMENT.map((e,i)=>`<button data-setup="equipment" data-value="${e}" class="equipment-tile ${d.equipment.includes(e)?'selected':''}" aria-pressed="${d.equipment.includes(e)}"><span class="equipment-code">${['DB','KB','SB','RB','BB','BW','PL','AW'][i]}</span><strong>${e}</strong><span class="tile-check">${d.equipment.includes(e)?'✓':'+'}</span></button>`).join('')}</div><h3 style="margin-top:26px">Excluded exercises</h3><p class="small">Any exercise whose name matches an exclusion will be filtered out.</p><div class="chips">${[...new Set(['Barbell Squat','Bench Press','Pull-up','Slams',...d.bans])].map(v=>`<button data-setup="ban" data-value="${esc(v)}" class="chip ${d.bans.includes(v)?'selected':''}" aria-pressed="${d.bans.includes(v)}">${d.bans.includes(v)?'✓ ': '+ '}${esc(v)}</button>`).join('')}</div><form id="setup-ban-form" class="inline-form"><input name="ban" aria-label="Exclude a movement" placeholder="Exclude another movement…" maxlength="80" required><button>Add</button></form><div class="builder-actions"><button class="primary" data-setup="step" data-value="2" ${!d.equipment.length?'disabled':''}>Choose my days</button></div>`;}

function daysStep(){const d=setupDraft,n=d.mode==='rotation'?d.target:d.days.length;return `<div class="eyebrow">02 / SCHEDULE TYPE</div><h2>Schedule type</h2><div class="focus-options">${[['rotation','Rolling rotation','Push → Pull → Lower. Continue where you left off, on any day.'],['fixed','Fixed weekdays','Assign a workout to each of your chosen weekdays.']].map(([v,name,desc])=>`<button data-setup="mode" data-value="${v}" class="${d.mode===v?'selected':''}" aria-pressed="${d.mode===v}"><strong>${name}</strong><span>${desc}</span></button>`).join('')}</div><h3>${d.mode==='rotation'?'Weekly session goal':'Training days per week'}</h3><div class="day-count">${[1,2,3,4,5,6,7].map(i=>`<button data-setup="count" data-value="${i}" class="${n===i?'selected':''}" aria-pressed="${n===i}">${i}</button>`).join('')}</div>${d.mode==='fixed'?`<div class="chips">${DAYS.map((name,i)=>`<button data-setup="day" data-value="${i}" class="chip ${d.days.includes(i)?'selected':''}" aria-pressed="${d.days.includes(i)}">${name.slice(0,3)}</button>`).join('')}</div><div class="fixed-assignments">${d.days.slice().sort((a,b)=>a-b).map((i,k)=>`<label>${DAYS[i]}<select data-assignment="${i}">${options(ROUTINES,d.assignments[i]||d.sequence[k%d.sequence.length])}</select></label>`).join('')}</div>`:`<p class="small">Your goal is ${d.target} completed sessions per week. Your ${d.sequence.length} workouts keep rotating across week boundaries.</p><h3 style="margin-top:24px">Workout order</h3><div class="rotation-order">${d.sequence.map((t,i)=>`<div><strong>${i+1}. ${t}</strong><button data-setup="move" data-value="${i}" ${i===0?'disabled':''} aria-label="Move ${t} earlier">Earlier</button></div>`).join('')}</div><p class="small">The next workout unlocks when the 20-minute session finishes. A skipped day never advances the sequence.</p>`}<div class="builder-actions"><button data-setup="step" data-value="1">Back</button><button class="primary" data-setup="step" data-value="3" ${d.mode==='fixed'&&!d.days.length?'disabled':''}>Preview my plan</button></div>`;}
function previewStep(){const p=plannedProfile(),d=setupDraft,n=d.mode==='rotation'?d.target:d.days.length,blocked=p.schedule.some((plan,i)=>plan.type!=='Rest'&&circuit(i,p).some(r=>!r.main));return `<div class="eyebrow">03 / YOUR PLAN</div><h2>${d.mode==='rotation'?'Rolling rotation':'Fixed weekly schedule'}</h2><p>${n} sessions per week · ${n*20} minutes</p>${d.mode==='rotation'?`<p style="margin-top:10px">${d.sequence.join(' → ')} → repeat. This plan starts with ${d.sequence[0]}.</p>`:''}<div class="plan-preview">${p.schedule.map((plan,i)=>`<details ${plan.type==='Rest'?'class="rest-preview"':''}><summary><span>${d.mode==='rotation'?`Workout ${i+1}`:DAYS[i]}</span><strong>${plan.type}</strong><small>${plan.type==='Rest'?'Recovery':'5 moves · 20 min'}</small></summary>${plan.type!=='Rest'?`<ol>${circuit(i,p).map(r=>`<li>${esc(r.main?.name||'No available move — adjust your filters')}</li>`).join('')}</ol>`:''}</details>`).join('')}</div>${blocked?'<div class="alert">Your filters leave empty slots. Adjust equipment or exclusions before applying.</div>':''}<p class="small">Applying replaces upcoming workouts and custom circuits, and starts the sequence from its first workout. Completed sessions and rep history stay saved.</p><div class="builder-actions"><button data-setup="step" data-value="2">Back</button><button class="primary" data-setup="apply" ${blocked||!n?'disabled':''}>Apply my setup</button></div>`;}
function applySetup(){if(hasActive()||!setupDraft)return;const draft=plannedProfile();if(!draft.schedule.length||!draft.schedule.some(d=>d.type!=='Rest')||draft.schedule.some((d,i)=>d.type!=='Rest'&&circuit(i,draft).some(r=>!r.main))){toast('Adjust your filters to fill all five slots.');return;}const p=profile();p.previousPlan={schedule:clone(p.schedule),mode:p.mode||'fixed',equipment:clone(p.equipment),bans:clone(p.bans),setup:clone(p.setup||null)};p.schedule=clone(draft.schedule);p.mode=draft.mode;p.weeklyTarget=draft.mode==='rotation'?setupDraft.target:setupDraft.days.length;p.rotationIndex=0;p.equipment=[...draft.equipment];p.bans=[...draft.bans];p.setup={mode:p.mode,days:setupDraft.days.slice(),updatedAt:Date.now()};p.workoutOverrides=null;p.session=null;previewSwaps={};day=defaultWorkoutIndex();tab='Workout';persist();render();toast('Your schedule and workouts are updated.');}
function weekGoal(){const p=profile(),goal=weeklyTarget(),d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);const from=localDate(d);d.setDate(d.getDate()+7);const to=localDate(d),count=p.history.filter(h=>h.date>=from&&h.date<to).length;return `<div class="week-goal"><div><span class="eyebrow">THIS WEEK · ${isRotation()?'ROLLING':'FIXED'}</span><strong>${count}<span> / ${goal} sessions</span></strong></div><div class="week-goal-track" role="progressbar" aria-label="Weekly training goal" aria-valuemin="0" aria-valuemax="${Math.max(goal,1)}" aria-valuenow="${Math.min(count,Math.max(goal,1))}"><i style="width:${goal?Math.min(100,count/goal*100):0}%"></i></div><button class="small" data-action="setup">Adjust plan</button></div>`;}
function circuitFingerprint(rows){return JSON.stringify(rows.map(r=>r.main?{name:r.main.name,equipment:[...r.main.equipment].sort(),reps:r.main.reps,description:r.main.description,weightKg:r.main.weightKg??savedLoad(r.main)}:null));}
function echoMatch(rows){const fingerprint=circuitFingerprint(rows);return profile().history.slice().reverse().find(h=>h.fingerprint===fingerprint&&h.echoEligible&&h.repLog?.some(e=>Number.isFinite(e.at)&&e.unit==='reps'));}
function echoPanel(s,rows){const match=s&&!s.echoInvalid?profile().history.slice().reverse().find(h=>h.fingerprint===s.fingerprint&&h.echoEligible&&h.repLog?.some(e=>Number.isFinite(e.at)&&e.unit==='reps')):s?null:echoMatch(rows);return `<div class="echo-panel"><div class="echo-heading"><span class="eyebrow">ECHO / PREVIOUS WORKOUT</span><button data-action="echo-toggle" aria-pressed="${!profile().echoOff}">${profile().echoOff?'Off':'On'}</button></div>${profile().echoOff?'<p>Comparison is off.</p>':s?.echoInvalid?'<p>Movement or load changed. Echo is off for this session so different circuits are not compared.</p>':match?`<strong id="echo-delta">${s?'Comparing rep counts':'Previous workout available'}</strong><div class="echo-tracks"><label>YOU <span id="echo-you">0</span></label><div><i id="echo-you-bar"></i></div><label>PREVIOUS <span id="echo-previous">0</span></label><div><i id="echo-previous-bar"></i></div></div><p>Compared at the same elapsed time · ${new Date(match.finishedAt).toLocaleDateString()}. Matched by exercises and recorded load. Rep pace only, not a strength score.</p>`:'<strong>No matching workout yet.</strong><p>Complete this circuit to record your rep timing. Echo compares it with your next session using the same exercises and recorded loads.</p>'}</div>`;}
function updateEcho(){const s=activeSession();if(!s||s.finished||s.day!==day||s.echoInvalid||profile().echoOff)return;const el=document.querySelector('#echo-delta');if(!el)return;const match=profile().history.slice().reverse().find(h=>h.fingerprint===s.fingerprint&&h.echoEligible&&h.repLog?.some(e=>Number.isFinite(e.at)&&e.unit==='reps'));if(!match)return;const elapsed=1200000-remaining(s),previous=match.repLog.filter(e=>e.unit==='reps'&&e.at<=elapsed).reduce((n,e)=>n+e.amount,0),now=countTotal(repEntries(s)),diff=now-previous,max=Math.max(1,now,previous,match.totalReps||0);el.textContent=diff===0?'Same rep count as last time':`${Math.abs(diff)} reps ${diff>0?'ahead of':'behind'} your previous pace`;document.querySelector('#echo-you').textContent=now;document.querySelector('#echo-previous').textContent=previous;document.querySelector('#echo-you-bar').style.width=now/max*100+'%';document.querySelector('#echo-previous-bar').style.width=previous/max*100+'%';}

document.addEventListener('click',e=>{const b=e.target.closest('[data-setup]');if(!b||b.disabled||!setupDraft)return;const a=b.dataset.setup,v=b.dataset.value,d=setupDraft;if(a==='step')d.step=Number(v);if(a==='equipment')d.equipment=d.equipment.includes(v)?d.equipment.filter(x=>x!==v):[...d.equipment,v];if(a==='ban')d.bans=d.bans.includes(v)?d.bans.filter(x=>x!==v):[...d.bans,v];if(a==='mode')d.mode=v;if(a==='count'){d.target=Number(v);d.days=SPACING[Number(v)].slice();}if(a==='day'){const i=Number(v);d.days=d.days.includes(i)?d.days.filter(x=>x!==i):[...d.days,i];}if(a==='move'){const i=Number(v);if(i>0)[d.sequence[i-1],d.sequence[i]]=[d.sequence[i],d.sequence[i-1]];}if(a==='apply'){applySetup();return;}render();});
document.addEventListener('change',e=>{if(e.target.dataset.assignment!==undefined&&setupDraft)setupDraft.assignments[Number(e.target.dataset.assignment)]=e.target.value;});
document.addEventListener('submit',e=>{if(e.target.id!=='setup-ban-form')return;e.preventDefault();const value=new FormData(e.target).get('ban').trim();if(norm(value).replace(/^no /,'').length<2){toast('Enter a movement name.');return;}if(!setupDraft.bans.includes(value))setupDraft.bans.push(value);render();});

